import{_ as n,o as i,c as t,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Icon-Styling deaktivieren","description":"Icon-Styling-Patching deaktivieren.","frontmatter":{"title":"Icon-Styling deaktivieren","description":"Icon-Styling-Patching deaktivieren."},"headers":[],"relativePath":"projects/uix/extras/disable-icon-styling.md","filePath":"projects/uix/extras/disable-icon-styling.md","lastUpdated":1793125707000}'),a={name:"projects/uix/extras/disable-icon-styling.md"};function r(c,e,l,s,d,g){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="icon-styling-patching-deaktivieren" tabindex="-1">Icon-Styling-Patching deaktivieren <a class="header-anchor" href="#icon-styling-patching-deaktivieren" aria-label="Permalink to &quot;Icon-Styling-Patching deaktivieren&quot;">​</a></h1><p>Diese Option verhindert, dass UIX Icon-Styling-Patches anwendet. Sie ist hilfreich, wenn eine Integration oder Custom Card eigene Icon-Logik nutzt und UIX diese nicht beeinflussen soll.</p><h2 id="einstellung-uber-die-integrations-ui" tabindex="-1">Einstellung über die Integrations-UI <a class="header-anchor" href="#einstellung-uber-die-integrations-ui" aria-label="Permalink to &quot;Einstellung über die Integrations-UI&quot;">​</a></h2><ol><li>In Home Assistant zu <strong>Settings -&gt; Devices &amp; Services -&gt; UI eXtension -&gt; Configure</strong> gehen.</li><li><strong>Performance settings</strong> oder den passenden Optionsbereich öffnen.</li><li><strong>Disable icon styling patching</strong> aktivieren.</li><li>Speichern.</li></ol><h2 id="verhalten-bei-aktivierter-option" tabindex="-1">Verhalten bei aktivierter Option <a class="header-anchor" href="#verhalten-bei-aktivierter-option" aria-label="Permalink to &quot;Verhalten bei aktivierter Option&quot;">​</a></h2><ul><li>UIX überschreibt keine Icons über <code>--uix-icon</code> oder <code>--uix-icon-for-&lt;entity_id&gt;</code>.</li><li>UIX überschreibt keine Icon-Farben über <code>--uix-icon-color</code> oder <code>--uix-icon-color-for-&lt;entity_id&gt;</code>.</li><li>Andere UIX-Styling-Funktionen bleiben verfügbar.</li></ul><h2 id="welche-anpassungen-entfallen" tabindex="-1">Welche Anpassungen entfallen? <a class="header-anchor" href="#welche-anpassungen-entfallen" aria-label="Permalink to &quot;Welche Anpassungen entfallen?&quot;">​</a></h2><p>Die Option ist standardmäßig nicht gesetzt. Nach dem Speichern gilt sie sofort für alle verbundenen Browser, ohne Neuladen. Die Standardelemente <code>ha-icon</code>, <code>ha-state-icon</code> und <code>ha-svg-icon</code> werden dann nicht mehr für Icon-Styling gepatcht oder überwacht. Überschreibungen mit <code>--uix-icon</code>, <code>--uix-icon-color</code>, <code>--uix-icon-dim</code> und <code>--uix-icon-for-*</code> greifen dort nicht mehr.</p>',8)])])}const p=n(a,[["render",r]]);export{u as __pageData,p as default};
